using UnityEngine;

/// <summary>Run-local prototype overlay and one reusable wave outline; no gameplay colliders.</summary>
[DisallowMultipleComponent]
public sealed class TitanicFistsVisual : MonoBehaviour
{
    private PlayerActor _player;
    private GameObject _overlay;
    private LineRenderer _wave;
    private Material _material;
    private float _remaining;
    public bool OverlayActive => _overlay && _overlay.activeInHierarchy;
    public bool WaveActive => _wave && _wave.gameObject.activeSelf;
    private void Awake() { _player = GetComponent<PlayerActor>(); }
    private bool Active => _player && _player.isActiveAndEnabled && !_player.IsDead &&
        _player.CurrentWeapon && WeaponRunModifiers.Identify(_player.CurrentWeapon) == RunWeaponFamily.Gauntlet &&
        _player.RunModifiers?.Expansion.MutationId(BoonSlot.Basic) == TitanicFistsDefinition.Id;
    private void EnsureMaterial()
    {
        if (_material) return;
        var shader = Shader.Find("Universal Render Pipeline/Unlit") ?? Shader.Find("Sprites/Default");
        _material = new Material(shader) { name = "Titanic Fists — runtime only", color = TitanicFistsDefinition.Color };
    }
    private void LateUpdate()
    {
        if (!Active) { Clear(); return; }
        if (!_overlay && _player.HandTransform)
        {
            EnsureMaterial();
            _overlay = new GameObject("Punhos Titânicos — visual only");
            _overlay.transform.SetParent(_player.HandTransform, false);
            for (int i = 0; i < 2; i++)
            {
                var plate = GameObject.CreatePrimitive(PrimitiveType.Cube);
                plate.name = "Angular gauntlet overlay";
                var collider = plate.GetComponent<Collider>(); collider.enabled = false; Destroy(collider);
                plate.transform.SetParent(_overlay.transform, false);
                plate.transform.localPosition = new Vector3(i == 0 ? -.09f : .09f, .02f, .06f);
                plate.transform.localRotation = Quaternion.Euler(0, 0, i == 0 ? -18 : 18);
                plate.transform.localScale = new Vector3(.16f, .28f, .34f);
                var renderer = plate.GetComponent<Renderer>(); renderer.sharedMaterial = _material;
                renderer.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            }
        }
        if (_wave && _wave.gameObject.activeSelf)
        {
            if (_player.IsCombatHitStopped || Time.timeScale <= 0 ||
                _player.TryGetComponent(out AbilityHolder holder) && holder.IsGamePaused) return;
            _remaining -= Time.deltaTime;
            if (_remaining <= 0) _wave.gameObject.SetActive(false);
        }
    }
    internal void ShowWave(Vector3 center, Vector3 forward, Vector3 size)
    {
        if (!Active) return;
        EnsureMaterial();
        if (!_wave)
        {
            var go = new GameObject("Punhos Titânicos — authorized shockwave");
            go.transform.SetParent(transform, false);
            _wave = go.AddComponent<LineRenderer>(); _wave.sharedMaterial = _material;
            _wave.useWorldSpace = true; _wave.loop = false; _wave.widthMultiplier = .10f;
            _wave.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            _wave.receiveShadows = false; _wave.positionCount = 8;
        }
        Vector3 right = Vector3.Cross(Vector3.up, forward).normalized;
        center.y = transform.position.y + .12f;
        Vector3 rear = center - forward * size.z * .5f, front = center + forward * size.z * .5f;
        _wave.SetPositions(new[] { rear - right * size.x * .5f, front - right * size.x * .5f,
            front + right * size.x * .5f, rear + right * size.x * .5f,
            rear - right * size.x * .5f, front - forward * size.z * .25f - right * size.x * .30f,
            front, front - forward * size.z * .25f + right * size.x * .30f });
        _remaining = .25f; _wave.gameObject.SetActive(true);
    }
    public void Clear()
    {
        if (_overlay) { _overlay.SetActive(false); Destroy(_overlay); _overlay = null; }
        if (_wave) _wave.gameObject.SetActive(false);
        _remaining = 0;
    }
    private void OnDisable() { Clear(); }
    private void OnDestroy() { Clear(); if (_material) Destroy(_material); }
}

