using System.Collections.Generic;
using UnityEngine;

public sealed partial class ProtocolRuntime
{
    private sealed class TitanicWork
    {
        public ProtocolExecution Child;
        public WeaponScript Weapon;
        public Vector3 Origin, Forward, Size;
        public float Range, Damage;
        public int Mask;
    }
    private readonly List<TitanicWork> _titanicWork = new List<TitanicWork>();
    internal int PendingTitanicWaves => _titanicWork.Count;
    public int TitanicWavesResolved { get; private set; }

    internal bool QueueTitanicFists(GauntletImpactContext parent, Vector3 origin, Vector3 forward,
        float range, Vector3 box, LayerMask layers, WeaponScript weapon)
    {
        if (!IsOpen || parent?.Snapshot?.BasicMutationId != TitanicFistsDefinition.Id ||
            !parent.Snapshot.BasicFinisher || !weapon || _player.CurrentWeapon != weapon ||
            !ReactionNumeric.IsFinite(origin) || !ReactionNumeric.IsFinite(forward) ||
            !ReactionNumeric.IsFinite(box) || !ReactionNumeric.IsFinite(range) || range <= 0 ||
            forward.sqrMagnitude < .0001f || box.x < 0 || box.y < 0 || box.z < 0) return false;
        var root = FindRoot(parent);
        if (root == null || root.ConfirmedBasicSourceDamage <= 0) return false;
        var child = ReserveConfirmedBasicChild(parent, ProtocolBasicEffects.None);
        if (child == null) return false;
        // Same fallback dimensions as PlayerActor.ResolveAttackBoxSize; expand resolved geometry only.
        box = new Vector3(box.x > 0 ? box.x : 2f, box.y > 0 ? box.y : 2f, box.z > 0 ? box.z : range);
        box.x *= TitanicFistsDefinition.GeometryMultiplier; box.z *= TitanicFistsDefinition.GeometryMultiplier;
        _titanicWork.Add(new TitanicWork { Child = child, Weapon = weapon, Origin = origin, Forward = forward.normalized,
            Range = range * TitanicFistsDefinition.GeometryMultiplier, Size = box,
            Damage = root.ConfirmedBasicSourceDamage * TitanicFistsDefinition.DamageCoefficient,
            Mask = layers.value != 0 ? layers.value : Physics.DefaultRaycastLayers });
        return true;
    }

    private void ClearTitanicFists()
    {
        foreach (var work in _titanicWork) work.Child.Dispose();
        _titanicWork.Clear();
        if (_player && _player.TryGetComponent(out TitanicFistsVisual visual)) visual.Clear();
    }

    private void TickTitanicFists()
    {
        for (int i = _titanicWork.Count - 1; i >= 0; i--)
        {
            if (i >= _titanicWork.Count) continue; // A damage callback may clear all remaining work.
            var work = _titanicWork[i];
            if (!work.Child.IsValid || !work.Child.IsLifecycleCurrent || !_player || _player.IsDead ||
                !_player.isActiveAndEnabled || _player.CurrentWeapon != work.Weapon ||
                _player.RunModifiers?.Expansion.MutationId(BoonSlot.Basic) != TitanicFistsDefinition.Id)
            { work.Child.Dispose(); _titanicWork.RemoveAt(i); continue; }
            if (!CanResolveBasicBranch || ScaledDelta <= 0 || _draining) continue;
            _titanicWork.RemoveAt(i);
            try { ResolveTitanicFists(work); }
            finally { work.Child.Dispose(); }
        }
    }

    private void ResolveTitanicFists(TitanicWork work)
    {
        var root = work.Child.Root;
        if (!Budget.ReserveQuery()) return;
        if (!root.HasImpactCapacity(1)) return;
        var center = work.Origin + work.Forward * (work.Range * .5f) + Vector3.up * (work.Size.y * .5f);
        int count = Physics.OverlapBoxNonAlloc(center, work.Size * .5f, _queryColliders,
            Quaternion.LookRotation(work.Forward), work.Mask, QueryTriggerInteraction.Collide);
        _queryTargets.Clear();
        for (int i = 0; i < count; i++)
        {
            var hit = _queryColliders[i]; _queryColliders[i] = null;
            var actor = hit ? hit.GetComponentInParent<Actor>() : null;
            if (!actor || actor.IsDead || !actor.isActiveAndEnabled || actor.Affiliation != CombatAffiliation.Enemy ||
                _queryTargets.Contains(actor)) continue;
            if (_boons && _boons.ProtocolSession != null && (!actor.TryGetComponent(out ProtocolEncounterMembership member) ||
                !member.Matches(root.SessionId, root.EncounterId))) continue;
            _queryTargets.Add(actor);
        }
        _queryTargets.Sort((a, b) => EntityId.ToULong(a.GetEntityId()).CompareTo(EntityId.ToULong(b.GetEntityId())));
        bool batch = root.BeginBatch();
        if (!batch) return;
        _draining = true; _processingBatch = true;
        try
        {
            using (OpenExecutionScope(work.Child))
            {
                int sightTests = 0;
                foreach (var actor in _queryTargets)
                {
                    if (++sightTests > _inventory.Catalog.Limits.SightTestsPerQuery) break;
                    Vector3 from = work.Origin + Vector3.up * .5f;
                    Vector3 delta = actor.transform.position + Vector3.up * .5f - from;
                    // Actor bodies are not solid scenery. Test every hit to avoid a nearby actor masking a wall.
                    bool blocked = false;
                    foreach (var obstacle in Physics.RaycastAll(from, delta.normalized, delta.magnitude,
                        Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore))
                        if (!obstacle.collider.GetComponentInParent<Actor>()) { blocked = true; break; }
                    if (!blocked) QueueDamage(root, actor, work.Damage, ProtocolProducer.Technique, 1, work.Child.BasicLineage, work.Child);
                }
                DrainDamage();
            }
            // The authorized wave stays readable even when it finds no NEW victim. Capacity was
            // checked without spending an empty damage impact; revocation still removes the visual.
            if (work.Child.IsValid && work.Child.IsLifecycleCurrent && Matches(root))
            {
                TitanicWavesResolved++;
                if (_player.TryGetComponent(out TitanicFistsVisual visual)) visual.ShowWave(center, work.Forward, work.Size);
            }
        }
        finally
        {
            while (_damageQueue.Count > 0) _damageQueue.Dequeue().Root.ReleaseQueueItem();
            root.EndBatch(); _draining = false; _processingBatch = false;
        }
    }
}

